export const WINDOWSLAB_SCENARIOS=winPresets.map(spec=>winAuthor(spec));

// Named negative fixtures are explicit test-only profiles, never extra catalog
// choices or a hidden runtime toggle. Their definitions cannot mutate presets.
export function buildWindowsNegativeFixture(scenarioId,variant){
  const spec=winPresets.find(item=>'lab-win-'+item.suffix===scenarioId);
  if(!spec||!spec.negativeCases?.includes(variant))throw new RangeError('Unknown Windows negative fixture: '+scenarioId+'/'+variant);
  const mode=variant==='required-mode-remote-credential-guard'?'remote-credential-guard':variant==='required-mode-restricted-admin'?'restricted-admin':spec.mode;
  return winAuthor({...spec,suffix:spec.suffix+'-negative-'+variant,mode,negativeCase:variant,register:false,title:spec.title+' - named test: '+variant});
}
